from pathlib import Path
import json,sys
sys.path.insert(0,str(Path('review').resolve()))
from auditlib import finding
root=Path.cwd()
items=[]
def add(i,sev,cat,title,path,needle,problem,trigger,actual,recommendation,effort='M',confidence='confirmed',lead='new',evidence=None,validation=None):
 s=(root/path).read_text(encoding='utf-8').splitlines();ln=next(k+1 for k,t in enumerate(s) if needle in t)
 x=dict(id=f'A-{i:03}',severity=sev,category=cat,title=title,location={'file':path,'line':ln,'quote':'\n'.join(s[ln-1:ln+2])},problem=problem,trigger_or_repro=trigger,expected_vs_actual=actual,evidence=evidence or f'Source inspection {path}:{ln}',recommendation=recommendation,effort=effort,confidence=confidence,lead=lead)
 if validation:x['validation']=validation
 items.append(x)
log='review/logs/parser-characterization-final.txt'
add(1,'P1','A','Overlapping boost detectors produce duplicate IDs and reject a valid replay','crates/replay-core/src/lib.rs','id: format!("{match_id}:{category}', 'Both segment types use the same category/player/start identifier. A player holding boost above 2200 with less than 10 boost for five seconds creates two equal IDs; validate_analysis rejects the whole replay.', 'review_validate_duplicate_events_fails_but_control_is_valid drives native Collector::process_frame snapshots for 6 seconds; change boost 0 to 33 as control.', 'Low boost case returns Analysis event references or time invalid; otherwise identical 33-boost case passes.', 'Give event types stable distinct identifiers, separate category from detector kind, and test simultaneous detectors.',evidence=log,validation='Actively disproved alternate cause: same collector snapshots with boost 33 instead of 0 validate successfully. Overlap control produces exactly two different titles with identical IDs; failure persists at finish_replay and regular flush.')
add(2,'P0','A','Low-boost event duration includes time while the player is absent','crates/replay-core/src/lib.rs','for car in &cars {','Accumulator segments are flushed only for currently present cars. When a player disappears, the outstanding low-boost/boost segment survives; returning or EOF closes it at the later replay time, asserting an unobserved interval.', 'review_absent_player_extends_observed_low_boost_event: six seconds low boost, six seconds with no car, then reappear.', 'Actual observed low-boost duration is 6 s; event is 0..12 and description says boost stayed below 10 continuously.', 'Flush or suspend segments when a player leaves the observable set, using last observed endpoint. Record an explicit missing-state interval.',evidence=log,validation='Native process_frame synthetic snapshots prove six seconds absent without increasing tracked_seconds. The event still extends to 12. No missing-data interpolation in the fixture or helper; current car set is empty during absence.')
add(3,'P0','A','Defensive-exposure event spans a timing gap that metrics explicitly exclude','crates/replay-core/src/lib.rs','if exposed != self.exposure_team {','When continuity fails, exposure is closed at the current time rather than the last continuous observation. A long skipped gap becomes part of a claimed observed exposure window.', 'review_exposure_event_spans_dropped_timing_gap: 1.2 seconds with two upfield defenders, next snapshot at 5 seconds.', 'Event is 0..5 although live_seconds is 1.2 and gap 1.2..5 is rejected.', 'Close exposure at previous continuous frame; clear exposure before processing discontinuities; test gap/goal/reset endpoints.',evidence=log,validation='Active disproof attempt: test verifies live_seconds remains 1.2, proving the interval is excluded by the metric but included by event construction. Both team players are present and correctly assigned.')
add(4,'P2','A','Player movement and resource baselines omit the kickoff approach','crates/replay-core/src/lib.rs','hit == Some(true) && !countdown','The shared live flag excludes all kickoff movement before first ball contact, beyond the countdown excluded by metric copy. Boost spent accelerating to kickoff and delayed/fake kickoff motion are absent from headline averages and measured active play.', 'review_kickoff_time_not_in_active_play; two seconds moving at 2250 with no first contact.', 'Zero tracked seconds and no boost/speed accumulation until after the first hit; copy says excludes countdown and goal celebration without naming kickoff approach.', 'Capture a gameplay phase enum and separate match/player-motion eligibility from ball-position eligibility. Document baseline semantics and create a kickoff report.',lead='confirmed',evidence=log)
add(5,'P2','A','Dropped observation gaps have no quantified quality or exclusion summary','crates/replay-core/src/lib.rs','let gap = !(0.0..=0.25).contains(&dt);','Gaps are marked as render discontinuities and silently removed from accumulation. Coverage cannot show gap count/seconds, excluded kickoff/goal time, per-player absence, or coverage ratio, so consumers cannot assess comparability.', 'review_gap_is_excluded_without_quality_accounting; 0.4-second gap in a short synthetic replay.', 'live_seconds excludes the gap but no coverage field explains how much was discarded.', 'Publish per-phase/per-metric observed and excluded durations with reason codes; require a coverage threshold for comparisons.',lead='confirmed',evidence=log)
add(6,'P2','A','Several metric sample counts describe all car frames, not valid observations','crates/replay-core/src/lib.rs','a.samples,','avg_speed and position metrics use a.samples even when velocity, team or ball is missing. The viewer tooltip prints sample_count as evidence, overstating supporting samples.', 'review_partial_velocity_overstates_metric_sample_count: 100 car samples with only one valid velocity.', 'avg_speed reports 100 samples but denominator is 0.1 s from a single observation.', 'Track valid sample counts separately for each sufficient-statistic denominator; show coverage duration as the main support.',evidence=log)
add(7,'P2','A','Analysis validator omits sufficient statistics and coverage integrity','crates/replay-core/src/lib.rs','if !ids.contains(m.player_id.as_str()) || m.value','Validator only checks metric player reference and value finiteness. Infinite numerator, negative denominator, inconsistent ratio, and NaN/live time beyond duration are accepted.', 'review_validator_accepts_corrupt_sufficient_statistics_and_coverage.', 'validate_analysis accepts negative denominator, infinite numerator and NaN coverage simultaneously.', 'Validate all numeric fields and nonnegative denominators; verify ratio/value consistency with tolerance and observed-time bounds.',evidence=log)
add(8,'P2','A','Analysis validator accepts impossible metric ranges and inconsistent shot attribution','crates/replay-core/src/lib.rs','for e in &a.shots {','Finite values alone allow negative scores, negative boost percentages, absurd sample indices and shot team disagreeing with the player. summary.players and recorder identity are not cross-checked against canonical players.', 'review_validator_accepts_negative_counts_and_wrong_shot_team sets score/boost -100, shot on opponent team, frame usize::MAX.', 'The validator accepts all constructed contradictions.', 'Add typed range validation by metric key, canonical participant consistency, recorder membership, and frame/index bounds.',evidence=log)
add(9,'P2','A','Duration is the last replay timestamp and includes non-gameplay time','crates/replay-core/src/lib.rs','duration_seconds: f64::from(last),','Replay elapsed end time is shown as Duration in Overview/Replays. It can include pre-game countdown, goal celebrations and end sequence, and does not subtract first frame time.', 'Inspect summary builder and Overview.tsx:200, Replays.tsx:416.', 'A replay ending at t=360 is displayed as 6:00 even if measured active play is 300; no match-versus-replay distinction.', 'Persist replay elapsed span, regulation/overtime time and observed player-motion duration separately; label them explicitly.',lead='confirmed')
add(10,'P2','A','Exact supersonic state is not measured; detector prose calls threshold time supersonic','crates/replay-core/src/lib.rs','Boost remained active while the car was already supersonic','Threshold accumulation is honestly named in dictionary, so missing hysteresis is not inherently wrong. The detector prose still equates >=2200 with game state, losing the 2100..2200 one-second grace interval and confusing exact state with a threshold approximation.', 'Inspect >=2200 cuts and metric dictionary limitations; official v1.78 notes document hysteresis as unchanged.', 'Threshold metric is valid as defined; exact state/time cannot be inferred from it, yet event calls the state supersonic.', 'Keep threshold metric, change event prose to at or above 2200, or derive a separate validated state estimate with hysteresis.',lead='confirmed',evidence='review/research-formulas/white-0.png; https://www.rocketleague.com/news/patch-notes-v1-78?lang=en (supersonic check)')
